def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Locate the solid 3 separator and use its thickness as the tile size.
    sep_rows = [r for r in range(h) if all(v == 3 for v in g[r])]
    sep_cols = [c for c in range(w) if all(g[r][c] == 3 for r in range(h))]

    horizontal = bool(sep_rows)
    if horizontal:
        s = len(sep_rows)
        sep_start, sep_end = min(sep_rows), max(sep_rows)
    elif sep_cols:
        s = len(sep_cols)
        sep_start, sep_end = min(sep_cols), max(sep_cols)
    else:
        return g

    pitch = s + 1

    # Find the repeated s-by-s pattern outside the separator.
    pattern = None
    for r in range(0, h - s + 1, pitch):
        for c in range(0, w - s + 1, pitch):
            if horizontal and r <= sep_end and r + s - 1 >= sep_start:
                continue
            if not horizontal and c <= sep_end and c + s - 1 >= sep_start:
                continue
            block = [g[r + i][c:c + s] for i in range(s)]
            if any(2 in row for row in block):
                pattern = [[1 if v == 2 else 0 for v in row] for row in block]
                break
        if pattern is not None:
            break

    if pattern is None:
        return g

    # Remove the separator.
    if horizontal:
        for r in range(sep_start, sep_end + 1):
            for c in range(w):
                g[r][c] = 0
    else:
        for r in range(h):
            for c in range(sep_start, sep_end + 1):
                g[r][c] = 0

    # Mark each tile at the cell indexed by its tile-grid coordinates.
    # Where that marked cell belongs to the pattern, fill a tile in the
    # separator as well.
    for r in range(0, h - s + 1, pitch):
        for c in range(0, w - s + 1, pitch):
            if horizontal:
                in_sep = sep_start <= r <= sep_end
            else:
                in_sep = sep_start <= c <= sep_end

            ir = (r // pitch) % s
            ic = (c // pitch) % s
            if not pattern[ir][ic]:
                continue

            has_tile = any(g[r + i][c + j] == 2
                           for i in range(s) for j in range(s))
            if in_sep and not has_tile:
                for i in range(s):
                    for j in range(s):
                        if pattern[i][j]:
                            g[r + i][c + j] = 2

            # Convert the indexed pattern cell to 8.
            if pattern[ir][ic]:
                g[r + ir][c + ic] = 8

    return g
